/* Pure product views. Actions use the existing workflow and authorization layer. */
(() => {
  'use strict';
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const text=(s,az,en)=>s.lang==='az'?az:en;
  const ordered=rules=>[...rules].sort((a,b)=>a.id.localeCompare(b.id,undefined,{numeric:true}));
  function statusKey(s,r) {
    const status=window.GpoProduct.controlStatus(s,r);
    if(!status.run)return 'unknown';
    if(String(status.run.result?.state).toUpperCase()==='ROLLED_BACK')return 'rolledback';
    return status.tone==='good'?'verified':status.tone==='warning'?'attention':'pending';
  }
  function matches(s,r) {
    return (!s.catalogSection||r.id.startsWith(s.catalogSection+'.'))&&
      (s.catalogSupport==='ALL'||r.implementation===s.catalogSupport)&&
      (s.catalogStatus==='ALL'||statusKey(s,r)===s.catalogStatus);
  }
  function header(s) {
    const connected=!!s.gpoSession?.connected&&!s.serviceOffline;
    return `<header class="studio-header"><div><span class="studio-breadcrumb">${text(s,'İş sahəsi / İcmal','Workspace / Overview')}</span><h1>${text(s,'Siyasət əməliyyatları','Policy operations')}</h1><p>${text(s,'Domen vəziyyətini yoxlayın, dəyişiklikləri planlaşdırın və nəticələri izləyin.','Review domain state, plan policy changes and follow their results.')}</p></div><div class="studio-header-actions"><button data-product-action="help">${text(s,'İstifadə bələdçisi','Workflow guide')}</button><a href="#/benchmark" class="studio-primary">${text(s,'Qayda seç','Choose a control')} <span aria-hidden="true">→</span></a></div></header><section class="studio-context" aria-label="${text(s,'İcra mühiti','Execution environment')}"><div><small>${text(s,'DOMEN','DOMAIN')}</small><strong>${esc(s.inventory?.domain||text(s,'Qoşulmayıb','Not connected'))}</strong>${s.inventory?.domainController?`<small class="studio-context-detail">${esc(s.inventory.domainController)}</small>`:''}</div><div><small>${text(s,'BAĞLANTI','CONNECTION')}</small><strong class="${connected?'studio-good':'studio-muted'}">${s.serviceOffline?text(s,'Xidmət offline','Service offline'):connected?text(s,'Qoşulub','Connected'):text(s,'Bağlantı gözlənilir','Awaiting connection')}</strong></div><div><small>GPO / ${text(s,'TƏTBİQ SAHƏSİ','SCOPES')}</small><strong>${s.inventory?`${s.inventory.gpos.length} / ${s.inventory.scopes.length}`:'— / —'}</strong></div><div><small>${text(s,'OPERATOR ROLU','OPERATOR ROLE')}</small><strong>${esc(s.session?.role||'—')}</strong>${s.inventory?.executionUser?`<small class="studio-context-detail">${esc(s.inventory.executionUser)}</small>`:''}</div><button data-product-action="${connected?'readiness':'connect'}">${connected?text(s,'Bağlantını yoxla','Check readiness'):text(s,'Domenə qoşul','Connect domain')} →</button>${connected?`<button class="studio-disconnect" data-disconnect>${text(s,'Ayrıl','Disconnect')}</button>`:''}</section>`;
  }
  function navigation(s) {
    const sections=s.catalog.sections.filter(x=>!x.parentId&&s.catalog.rules.some(r=>r.id.startsWith(x.id+'.')));
    return `<nav class="studio-sections" aria-label="${text(s,'Benchmark bölmələri','Benchmark sections')}"><div class="studio-section-title">${text(s,'BÖLMƏLƏR','SECTIONS')}</div><button data-catalog-section="" aria-pressed="${!s.catalogSection}"><span>${text(s,'Bütün qaydalar','All controls')}</span><b>${s.catalog.rules.length}</b></button>${sections.map(x=>`<button data-catalog-section="${esc(x.id)}" aria-pressed="${s.catalogSection===x.id}"><span><i>${esc(x.id)}</i>${esc(x.title)}</span><b>${s.catalog.rules.filter(r=>r.id.startsWith(x.id+'.')).length}</b></button>`).join('')}</nav>`;
  }
  function summary(s) {
    const rules=s.catalog.rules;
    return `<section class="friendly-summary" aria-label="${text(s,'Kataloq xülasəsi','Catalog summary')}">${[[rules.length,text(s,'Bütün qaydalar','All controls'),'total'],[rules.filter(r=>r.implementation==='live').length,text(s,'Avtomatik tətbiqə hazır','Ready for automation'),'ready'],[rules.filter(r=>r.implementation==='manual').length,text(s,'Əl ilə yoxlanılır','Reviewed manually'),'manual']].map(([count,label,tone])=>`<div class="${tone}"><span>${label}</span><strong>${count}</strong></div>`).join('')}</section>`;
  }
  function filters(s) {
    const options=(items,value)=>items.map(([v,label])=>`<option value="${v}" ${v===value?'selected':''}>${label}</option>`).join('');
    return `<div class="studio-status-filters"><label>${text(s,'İcra dəstəyi','Execution support')}<select id="catalog-support">${options([['ALL',text(s,'Bütün dəstək növləri','All support types')],['live',text(s,'Avtomatlaşdırma hazır','Automation ready')],['manual',text(s,'Əl ilə yoxlama','Manual review')],['unavailable',text(s,'Mapping mövcud deyil','Mapping unavailable')]],s.catalogSupport)}</select></label><label>${text(s,'Son tətbiq qeydi','Last implementation record')}<select id="catalog-status">${options([['ALL',text(s,'Bütün statuslar','All statuses')],['unknown',text(s,'Yoxlanmayıb','Not assessed')],['verified',text(s,'Tətbiq təsdiqlənib','Implementation verified')],['attention',text(s,'Yoxlama tələb edir','Needs review')],['pending',text(s,'İcra / təsdiq gözlənilir','In progress / pending')],['rolledback',text(s,'Geri qaytarılıb','Rolled back')]],s.catalogStatus)}</select></label><span>${text(s,'Statuslar qeydə alınmış əməliyyatları göstərir.','Statuses reflect recorded operations.')}</span></div>`;
  }
  function table(s,rules) {
    const sorted=ordered(rules),size=40,pages=Math.max(1,Math.ceil(sorted.length/size)),page=Math.max(1,Math.min(s.catalogPage||1,pages)),rows=sorted.slice((page-1)*size,page*size);
    if(!rows.length)return `<section class="studio-empty" role="status"><h2>${text(s,'Uyğun qayda tapılmadı','No matching controls')}</h2><p>${text(s,'Axtarış və filtrləri dəyişərək yenidən baxın.','Adjust the search and filters to try again.')}</p><button data-product-action="clear-filters">${text(s,'Filtrləri təmizlə','Clear filters')}</button></section>`;
    return `<div class="studio-table-wrap"><table class="studio-table"><caption class="studio-sr-only">${text(s,'CIS qaydaları və son qeydə alınmış nəticələr','CIS controls and last recorded outcomes')}</caption><thead><tr><th scope="col">${text(s,'Qayda','Control')}</th><th scope="col">${text(s,'İcra dəstəyi','Execution support')}</th><th scope="col">${text(s,'Son tətbiq qeydi','Last implementation record')}</th><th scope="col"><span class="studio-sr-only">${text(s,'Seçilmişlər','Favorites')}</span>★</th></tr></thead><tbody>${rows.map(r=>{const status=window.GpoProduct.controlStatus(s,r);return `<tr><td><div class="studio-control-cell"><span class="studio-control-id">${esc(r.id)}</span><div><button data-rule="${esc(r.id)}">${esc(r.title)}</button><small>${esc(r.level)} · ${esc(r.recommended||text(s,'Tövsiyə üçün qaydanı açın','Open control for recommendation'))}</small></div></div></td><td><span class="studio-badge ${r.implementation==='live'?'ready':'neutral'}">${r.implementation==='live'?text(s,'Hazır','Ready'):r.implementation==='manual'?text(s,'Əl ilə','Manual'):text(s,'Mövcud deyil','Unavailable')}</span></td><td><span class="studio-badge ${status.tone}">${status.label}</span>${status.run?`<small>${esc(status.run.plan?.preview?.gpo?.name||'GPO')} · ${window.GpoProduct.date(status.run.updatedAt,s.lang)}</small>`:''}</td><td><button class="studio-favorite" data-favorite="${esc(r.id)}" aria-label="${esc(r.id)} · ${text(s,'Seçilmiş statusunu dəyiş','Toggle favorite')}" aria-pressed="${s.favorites.has(r.id)}">${s.favorites.has(r.id)?'★':'☆'}</button></td></tr>`;}).join('')}</tbody></table><footer class="studio-pagination"><span>${(page-1)*size+1}–${Math.min(page*size,sorted.length)} / ${sorted.length} ${text(s,'qayda','controls')}</span><div><button data-catalog-page="${page-1}" ${page===1?'disabled':''} aria-label="${text(s,'Əvvəlki səhifə','Previous page')}">←</button><span>${page} / ${pages}</span><button data-catalog-page="${page+1}" ${page===pages?'disabled':''} aria-label="${text(s,'Növbəti səhifə','Next page')}">→</button></div></footer></div>`;
  }
  function loading(s) {
    return `<section class="studio-loading" role="status"><span class="studio-breadcrumb">GPO Remediator</span><h1>${text(s,'İş sahəsi açılır','Opening workspace')}</h1><p>${text(s,'Benchmark kataloqu yüklənir…','Loading benchmark catalog…')}</p><div class="studio-skeleton" aria-hidden="true"></div><div class="studio-skeleton" aria-hidden="true"></div><div class="studio-skeleton" aria-hidden="true"></div></section>`;
  }
  window.GpoStudio=Object.freeze({header,navigation,summary,filters,table,matches,statusKey,ordered,loading});
})();
